var suggestions=document.getElementById('suggestions'),search=document.getElementById('search');search!==null&&document.addEventListener('keydown',inputFocus);function inputFocus(a){a.ctrlKey&&a.key==='/'&&(a.preventDefault(),search.focus()),a.key==='Escape'&&(search.blur(),suggestions.classList.add('d-none'))}document.addEventListener('click',function(a){var b=suggestions.contains(a.target);b||suggestions.classList.add('d-none')}),document.addEventListener('keydown',suggestionFocus);function suggestionFocus(c){const d=suggestions.classList.contains('d-none');if(d)return;const a=[...suggestions.querySelectorAll('a')];if(a.length===0)return;const b=a.indexOf(document.activeElement);if(c.key==="ArrowUp"){c.preventDefault();const d=b>0?b-1:0;a[d].focus()}else if(c.key==="ArrowDown"){c.preventDefault();const d=b+1<a.length?b+1:b;a[d].focus()}}(function(){var a=new FlexSearch.Document({tokenize:"forward",cache:100,document:{id:'id',store:["href","title","description"],index:["title","description","content"]}});a.add({id:0,href:"/fr/docs/qualite/",title:"Démarche qualité",description:"",content:""}).add({id:1,href:"/fr/docs/ednac/nac_1_qualebook/",title:"Qualité du livre numérique",description:"Mise à jour : juin 2025\nDurée : 7 heures\nObjectifs #  Comprendre les enjeux de qualité pour le livre numérique Connaître les principaux axes de la qualité pour le livre numérique Savoir utiliser Qualebook, la liste de référence qualité du livre numérique  Programme #  La démarche qualité  Maîtriser les risques Planifier les évolutions Amélioration continue   Les enjeux du livre numérique  accessibilité utilisabilité lisibilité fiabilité écoconception légalité découvrabilité interopérabilité   Utiliser Qualebook, la liste de référence qualité  L’écriture des règles, un processus continu À chaque acteur sa portion Intégrer les règles dans les outils métiers.",content:"Mise à jour : juin 2025\nDurée : 7 heures\nObjectifs #  Comprendre les enjeux de qualité pour le livre numérique Connaître les principaux axes de la qualité pour le livre numérique Savoir utiliser Qualebook, la liste de référence qualité du livre numérique  Programme #  La démarche qualité  Maîtriser les risques Planifier les évolutions Amélioration continue   Les enjeux du livre numérique  accessibilité utilisabilité lisibilité fiabilité écoconception légalité découvrabilité interopérabilité   Utiliser Qualebook, la liste de référence qualité  L’écriture des règles, un processus continu À chaque acteur sa portion Intégrer les règles dans les outils métiers.    Public # Professions de l’édition en lien avec le livre numérique\nPré requis # Piloter ou participer à des projets d’édition, de diffusion ou de distribution numérique. Un profil technique n’est pas nécessaire.\nMoyens pédagogiques #  Méthode active alternant apports théoriques, démonstrations et ateliers pratiques. Études de cas concrets à partir de situations des participants. Échanges personnalisés. Guide de référence, ressources et exercices.  Évaluation #  QCM. Évaluation orale à chaud. Questionnaire à froid.  Formateur # 25 ans d\u0026rsquo;expérience dans la production éditoriale dont 12 ans de pratique de publication adaptées à des besoins spécifiques. Formateur confirmé.\ntarif # Tous nos tarifs sont hors taxe et exonérés de TVA (article 261.4.4 a du CGI)\n Inter entreprises : 500 euros par personne. Inter entreprise à distance : 300 euros par personne. Intra entreprise : 1500 euros (jusqu\u0026rsquo;à 8 personnes).  dates et modalités #  Formation accessible aux personnes en situation de handicap. Inscription 3 semaines avant le début de la formation. Les sessions inter entreprises sont ouvertes à partir de 3 inscrits. Les sessions à distance se tiennent via l\u0026rsquo;application Zoom sur deux demi journées. Sessions à distance (pas de session programmée) Sessions inter en entreprise à Montpellier (pas de session programmée) Contact: formations @ editadapt.net (supprimer les espaces)  "}).add({id:2,href:"/fr/docs/edada/ad_1_enjeux/",title:"Enjeux de l'édition numérique",description:"Mise à jour : novembre 2023\nDurée : 21 heures sur 3 jours\nComprendre les évolutions en cours et leurs utilités pour l'accès à la lecture, savoir se positionner et anticiper. Un programme d\u0026rsquo;une journée.\nObjectifs #  Comprendre les enjeux de l\u0026rsquo;édition numérique accessible. Comprendre les formats structurés, et leur interopérabilité. Savoir organiser la production pour répondre au besoin de mutualisation. Savoir produire un document de bureautique accessible.  Programme #  Brève histoire de l\u0026rsquo;édition numérique.",content:"Mise à jour : novembre 2023\nDurée : 21 heures sur 3 jours\nComprendre les évolutions en cours et leurs utilités pour l'accès à la lecture, savoir se positionner et anticiper. Un programme d\u0026rsquo;une journée.\nObjectifs #  Comprendre les enjeux de l\u0026rsquo;édition numérique accessible. Comprendre les formats structurés, et leur interopérabilité. Savoir organiser la production pour répondre au besoin de mutualisation. Savoir produire un document de bureautique accessible.  Programme #  Brève histoire de l\u0026rsquo;édition numérique. Définition et histoire des formats pivots XML, DAISY, HTML, CSS etEPUB. Gestion des métadonnées. Bonnes pratiques et recommandations sur les flux de travail Balisage, contenu linéaire, accessibilité, assemblage, exportations. Cas pratique avec trois logiciels de traitement de texte : Word,Google doc, LibreOffice.  Public # Équipes de direction.\nPré requis # Gérer des équipes dédiées à la publication de documents accessibles ou adaptés.\nMoyens pédagogiques #  Méthode active alternant apports théoriques, démonstrations et ateliers pratiques. Études de cas concrets à partir de situations des participants. Échanges personnalisés. Guide de référence, ressources et exercices.  Évaluation #  QCM. Évaluation orale à chaud. Questionnaire à froid.  Formateur # 25 ans d\u0026rsquo;expérience dans la production éditoriale dont 12 ans de pratique de publication adaptées à des besoins spécifiques. Formateur confirmé.\ntarif # Tous nos tarifs sont hors taxe et exonérés de TVA (article 261.4.4 a du CGI)\n Inter entreprises : 500 euros par personne. Inter entreprise à distance : 300 euros par personne. Intra entreprise : 1500 euros (jusqu\u0026rsquo;à 8 personnes).  dates et modalités #  Formation accessible aux personnes en situation de handicap. Inscription 3 semaines avant le début de la formation. Les sessions inter entreprises sont ouvertes à partir de 3 inscrits. Les sessions à distance se tiennent via l\u0026rsquo;application Zoom sur deux demi journées. Sessions à distance (pas de session programmée) Sessions inter en entreprise à Montpellier (pas de session programmée) Contact: formations @ editadapt.net (supprimer les espaces)  "}).add({id:3,href:"/fr/docs/ednac/nac_1_enjeux/",title:"Enjeux du livre numérique accessible",description:"Mise à jour : novembre 2023\nDurée : 7 heures\nObjectifs #  Connaître les évolutions légales Comprendre les besoins spécifiques liés à la lecture Comprendre les implications sur les chaines de production Maîtriser les enjeux liés au livre numérique accessible  Programme #  La famine du livre Handicap \u0026amp; déficience, contexte \u0026amp; situations de lecture Cadre légal international, européen et national Impact sur les métiers, compétences à mobiliser Avantages et difficultés des différentes solutions de production (traitements de texte, InDesign, langages de balisage) Interopérabilités, mutualisations Évaluation et indicateurs de suivi  Public # Éditeurs, responsables de publication, directeur de collection.",content:"Mise à jour : novembre 2023\nDurée : 7 heures\nObjectifs #  Connaître les évolutions légales Comprendre les besoins spécifiques liés à la lecture Comprendre les implications sur les chaines de production Maîtriser les enjeux liés au livre numérique accessible  Programme #  La famine du livre Handicap \u0026amp; déficience, contexte \u0026amp; situations de lecture Cadre légal international, européen et national Impact sur les métiers, compétences à mobiliser Avantages et difficultés des différentes solutions de production (traitements de texte, InDesign, langages de balisage) Interopérabilités, mutualisations Évaluation et indicateurs de suivi  Public # Éditeurs, responsables de publication, directeur de collection.\nPré requis # Compréhension des métiers de l\u0026rsquo;édition.\nMoyens pédagogiques #  Méthode active alternant apports théoriques, démonstrations et ateliers pratiques. Études de cas concrets à partir de situations des participants. Échanges personnalisés. Guide de référence, ressources et exercices.  Évaluation #  QCM. Évaluation orale à chaud. Questionnaire à froid.  Formateur # 25 ans d\u0026rsquo;expérience dans la production éditoriale dont 12 ans de pratique de publication adaptées à des besoins spécifiques. Formateur confirmé.\ntarif # Tous nos tarifs sont hors taxe et exonérés de TVA (article 261.4.4 a du CGI)\n Inter entreprises : 500 euros par personne. Inter entreprise à distance : 300 euros par personne. Intra entreprise : 1500 euros (jusqu\u0026rsquo;à 8 personnes).  dates et modalités #  Formation accessible aux personnes en situation de handicap. Inscription 3 semaines avant le début de la formation. Les sessions inter entreprises sont ouvertes à partir de 3 inscrits. Les sessions à distance se tiennent via l\u0026rsquo;application Zoom sur deux demi journées. Sessions à distance (pas de session programmée) Sessions inter en entreprise à Montpellier (pas de session programmée) Contact: formations @ editadapt.net (supprimer les espaces)  "}).add({id:4,href:"/fr/docs/partenaires/",title:"Partenariats",description:"",content:""}).add({id:5,href:"/fr/docs/ednac/nac_7_controle/",title:"Contrôler, améliorer et renseigner un livre numérique accessible au format EPUB",description:"Mise à jour : novembre 2023\nDurée : 21 heures sur 3 jours\nObjectifs #  Savoir contrôler le niveau d\u0026rsquo;accessibilité Savoir établir et renseigner des indicateurs de suivi Savoir renseigner et informer sur les fonctionalités et l\u0026rsquo;accessibilité des fichiers  Programme #  Contrôles automatisés (epubcheck \u0026amp; ACE) Contrôles manuels Rapport d\u0026rsquo;évaluation Exemple : SMART Métadonnées et vocabulaire Publication des conformités Plan d\u0026rsquo;évolutions  Public # Service de fabrication, responsable qualité.",content:"Mise à jour : novembre 2023\nDurée : 21 heures sur 3 jours\nObjectifs #  Savoir contrôler le niveau d\u0026rsquo;accessibilité Savoir établir et renseigner des indicateurs de suivi Savoir renseigner et informer sur les fonctionalités et l\u0026rsquo;accessibilité des fichiers  Programme #  Contrôles automatisés (epubcheck \u0026amp; ACE) Contrôles manuels Rapport d\u0026rsquo;évaluation Exemple : SMART Métadonnées et vocabulaire Publication des conformités Plan d\u0026rsquo;évolutions  Public # Service de fabrication, responsable qualité.\nPré requis # Connaître le format EPUB et sa fabrication.\nMoyens pédagogiques #  Méthode active alternant apports théoriques, démonstrations et ateliers pratiques. Études de cas concrets à partir de situations des participants. Échanges personnalisés. Guide de référence, ressources et exercices.  Évaluation #  QCM. Évaluation orale à chaud. Questionnaire à froid.  Formateur # 25 ans d\u0026rsquo;expérience dans la production éditoriale dont 12 ans de pratique de publication adaptées à des besoins spécifiques. Formateur confirmé.\ntarif # Tous nos tarifs sont hors taxe et exonérés de TVA (article 261.4.4 a du CGI)\n Inter entreprises : 500 euros par personne. Inter entreprise à distance : 300 euros par personne. Intra entreprise : 1500 euros (jusqu\u0026rsquo;à 8 personnes).  dates et modalités #  Formation accessible aux personnes en situation de handicap. Inscription 3 semaines avant le début de la formation. Les sessions inter entreprises sont ouvertes à partir de 3 inscrits. Les sessions à distance se tiennent via l\u0026rsquo;application Zoom sur deux demi journées. Sessions à distance (pas de session programmée) Sessions inter en entreprise à Montpellier (pas de session programmée) Contact: formations @ editadapt.net (supprimer les espaces)  "}).add({id:6,href:"/fr/docs/edada/ad_3_structure/",title:"Créer et transformer des fichiers structurés",description:"XML, DAISY et EPUB, un programme de 3 jours permettant de savoir utiliser ces trois formats pour des contenus simples (textes et images).\nMise à jour : novembre 2023\nDurée : 21 heures sur 3 jours\nObjectifs #  Comprendre les enjeux de l\u0026rsquo;édition numérique accessible. Comprendre les formats structurés, et leur interopérabilité. Savoir traiter un fichier XML pour une adaptation en gros caractères,en braille ou pour une adaptation numérique accessible (epub et pdf).",content:"XML, DAISY et EPUB, un programme de 3 jours permettant de savoir utiliser ces trois formats pour des contenus simples (textes et images).\nMise à jour : novembre 2023\nDurée : 21 heures sur 3 jours\nObjectifs #  Comprendre les enjeux de l\u0026rsquo;édition numérique accessible. Comprendre les formats structurés, et leur interopérabilité. Savoir traiter un fichier XML pour une adaptation en gros caractères,en braille ou pour une adaptation numérique accessible (epub et pdf). Savoir créer un fichier DAISY, l\u0026rsquo;améliorer et le transformer. Savoir transformer un fichier epub pour une adaptation en groscaractères ou en braille. Savoir créer et modifier un fichier epub3 accessible et le vérifier.  Programme #  Définition et histoire des formats pivots XML, DAISY, HTML, CSS etEPUB. Gestion des métadonnées. Création d\u0026rsquo;un fichier XML dtBook (DAISY). Transformation d\u0026rsquo;un fichier XML dtBook (DAISY) aux formats epub etdbt. Création d\u0026rsquo;un fichier epub3 accessible. Utilisation de Calibre pour transformer un fichier epub. Modifications d\u0026rsquo;un fichier epub. Transformation et importation d\u0026rsquo;un fichier XML éditeur. Automatisations, modèles de fichiers et bonnes pratiques.  Public # Transcripteurs adaptateurs.\nPré requis # Moyens pédagogiques #  Méthode active alternant apports théoriques, démonstrations et ateliers pratiques. Études de cas concrets à partir de situations des participants. Échanges personnalisés. Guide de référence, ressources et exercices.  Évaluation #  QCM. Évaluation orale à chaud. Questionnaire à froid.  Formateur # 25 ans d\u0026rsquo;expérience dans la production éditoriale dont 12 ans de pratique de publication adaptées à des besoins spécifiques. Formateur confirmé.\ntarif # Tous nos tarifs sont hors taxe et exonérés de TVA (article 261.4.4 a du CGI)\n Inter entreprises : 500 euros par personne. Inter entreprise à distance : 300 euros par personne. Intra entreprise : 1500 euros (jusqu\u0026rsquo;à 8 personnes).  dates et modalités #  Formation accessible aux personnes en situation de handicap. Inscription 3 semaines avant le début de la formation. Les sessions inter entreprises sont ouvertes à partir de 3 inscrits. Les sessions à distance se tiennent via l\u0026rsquo;application Zoom sur deux demi journées. Sessions à distance (pas de session programmée) Sessions inter en entreprise à Montpellier (pas de session programmée) Contact: formations @ editadapt.net (supprimer les espaces)  "}).add({id:7,href:"/fr/docs/edada/",title:"Édition adaptée",description:"La réalité de l’édition adaptée est fortement modifiée par la loi exception handicap qui donne aux centre d’adaptation accès aux fichiers numériques des éditeurs. C’est une occasion de proposer un meilleur service à un plus grand nombre d’usagers et d’avancer dans la voie d’une égalité d\u0026rsquo;accès à la lecture. Pour en bénéficier pleinement, il est nécessaire de repenser notre approche technique et d’assurer une montée en compétence des professionnels. En plus de leurs compétences spécifiques, les transcripteurs adaptateurs doivent aujourd’hui comprendre et s’approprier les outils de l’édition et du web pour répondre aux besoins précis de l’usager.",content:"La réalité de l’édition adaptée est fortement modifiée par la loi exception handicap qui donne aux centre d’adaptation accès aux fichiers numériques des éditeurs. C’est une occasion de proposer un meilleur service à un plus grand nombre d’usagers et d’avancer dans la voie d’une égalité d\u0026rsquo;accès à la lecture. Pour en bénéficier pleinement, il est nécessaire de repenser notre approche technique et d’assurer une montée en compétence des professionnels. En plus de leurs compétences spécifiques, les transcripteurs adaptateurs doivent aujourd’hui comprendre et s’approprier les outils de l’édition et du web pour répondre aux besoins précis de l’usager.\nL’enjeux est de permettre une mutualisation efficace d’ouvrages adaptés non pas pour un besoin précis, mais dans des formats de fichier pivots permettant une adaptation rapide et précise au plus près des besoins de l’usager.\nConscient de la diversité des acteurs, nous proposons des solutions adaptées aux moyens de chaque structure, tout en conservant l’interopérabilité nécessaire à la mutualisation.\n"}).add({id:8,href:"/fr/docs/ednac/",title:"Nativement accessible",description:"L\u0026rsquo;édition numérique ouvre des possibles en matière d\u0026rsquo;accès à l\u0026rsquo;information et à la connaissance.\nAu delà des obligations légales en cours de formalisation, nous proposons des formations destinées à vous permettre de toucher le plus grand nombre de lecteurs et à tirer le meilleur parti du numérique pour vos flux de production.",content:"L\u0026rsquo;édition numérique ouvre des possibles en matière d\u0026rsquo;accès à l\u0026rsquo;information et à la connaissance.\nAu delà des obligations légales en cours de formalisation, nous proposons des formations destinées à vous permettre de toucher le plus grand nombre de lecteurs et à tirer le meilleur parti du numérique pour vos flux de production.\n"}).add({id:9,href:"/fr/docs/introduction/",title:"Formations",description:"Éditadapt accompagne techniquement et renforce les compétences des acteurs de l\u0026rsquo;édition impliqués dans une démarche d\u0026rsquo;accessibilité de leurs productions.\nNotre approche s’inscrit dans la riche histoire des technique de l’édition et la convergence des univers de la lecture numérique, de l’édition traditionnelle et des besoins spécifiques pour les publics jusque là empêchés de lire.\nNous adaptons nos formations à vos besoins. Contactez-nous : formation @ editadapt.net.\nEn 2021 100 % des stagiaires répondants déclarent avoir atteint les objectifs et que la formation leur a permis d\u0026rsquo;augmenter leur niveau de connaissance et d\u0026rsquo;habileté.",content:"Éditadapt accompagne techniquement et renforce les compétences des acteurs de l\u0026rsquo;édition impliqués dans une démarche d\u0026rsquo;accessibilité de leurs productions.\nNotre approche s’inscrit dans la riche histoire des technique de l’édition et la convergence des univers de la lecture numérique, de l’édition traditionnelle et des besoins spécifiques pour les publics jusque là empêchés de lire.\nNous adaptons nos formations à vos besoins. Contactez-nous : formation @ editadapt.net.\nEn 2021 100 % des stagiaires répondants déclarent avoir atteint les objectifs et que la formation leur a permis d\u0026rsquo;augmenter leur niveau de connaissance et d\u0026rsquo;habileté.\nConditions générales de vente et Règlement intérieur disponibles sur demande\nRéclamation # Pour toute réclamation ou demande relative à la qualité de la formation, veuillez nous faire parvenir un email à l\u0026rsquo;adresse gautier @ editadapt.net. Un accusé de réception vous sera communiqué en moins de 24 heures et une réponse personnalisée sous 72 heures.\n"}).add({id:10,href:"/fr/docs/qualite/ea_cgvs/",title:"Conditions Générales de Vente des Prestations de Formation ",description:"Conditions Générales de Vente des Prestations de Formation par CHOMEL Gautier - EDITADAPT\n(Ci-après « les Conditions Générales de Vente), Micro entreprise dont le siège social est situé 10 rue de la salle l\u0026rsquo;eveque, 34000 montpellier et dont le numéro d\u0026rsquo;identification est SIRET 48376458500038\n(ci-après « Éditadapt »). Mis à jour le 28 avril 2022\nArticle 1 : Prestations vendues # Les actions de formation dispensées par Éditadapt rentrent dans le cadre de la formation professionnelle et des dispositions de l\u0026rsquo;article L 6313-1 du Code du travail et sont donc réalisées conformément à un programme préétabli qui, en fonction d\u0026rsquo;objectifs déterminés, précise les moyens pédagogiques, les moyens techniques et d\u0026rsquo;encadrement mis en œuvre ainsi que les processus permettant de suivre son exécution et d\u0026rsquo;en apprécier les résultats.",content:"Conditions Générales de Vente des Prestations de Formation par CHOMEL Gautier - EDITADAPT\n(Ci-après « les Conditions Générales de Vente), Micro entreprise dont le siège social est situé 10 rue de la salle l\u0026rsquo;eveque, 34000 montpellier et dont le numéro d\u0026rsquo;identification est SIRET 48376458500038\n(ci-après « Éditadapt »). Mis à jour le 28 avril 2022\nArticle 1 : Prestations vendues # Les actions de formation dispensées par Éditadapt rentrent dans le cadre de la formation professionnelle et des dispositions de l\u0026rsquo;article L 6313-1 du Code du travail et sont donc réalisées conformément à un programme préétabli qui, en fonction d\u0026rsquo;objectifs déterminés, précise les moyens pédagogiques, les moyens techniques et d\u0026rsquo;encadrement mis en œuvre ainsi que les processus permettant de suivre son exécution et d\u0026rsquo;en apprécier les résultats.\nChaque formation dispensée par Éditadapt porte un numéro d\u0026rsquo;identification unique, une dénomination, un titre et un contenu.\nLa participation aux formations dispensées par Éditadapt implique de la part de l\u0026rsquo;acheteur desdites prestations (ci-après dénommé « le Client) que ce dernier veille à ce que les participants inscrits possèdent bien les connaissances requises et/ou y répondent en termes de compétence pour pouvoir suivre les formations.\nArticle 2 : Application des conditions générales de vente de prestations de formation \u0026ndash; Durée # Les présentes Conditions Générales de Vente sont applicables à toute commande de formation passée par un Client auprès de Éditadapt.\nLe simple fait d\u0026rsquo;assister, en personne ou par l\u0026rsquo;un de ses préposés, à une séance de formation implique l\u0026rsquo;adhésion entière et sans réserve du Client aux présentes Conditions Générales de Vente pour la durée des relations contractuelles liées aux formations. Ainsi, la passation de commande ou l\u0026rsquo;assistance à une séance de formation vaut acceptation expresse et sans réserve par le Client des présentes Conditions Générales de Vente, lesquelles prévaudront sur toutes autres conditions.\nCelles-ci ne peuvent être modifiées que par un écrit signé par le Client et un responsable de Éditadapt dûment habilité à cet effet.\nLe fait que Éditadapt ne se prévale pas à un moment donné de l\u0026rsquo;une quelconque des présentes Conditions Générales de Vente ne peut être interprété comme valant renonciation à se prévaloir ultérieurement de l\u0026rsquo;une quelconque desdites conditions.\nArticle 3 : Champ d\u0026rsquo;application # Les présentes Conditions Générales de Vente s\u0026rsquo;appliquent à toutes les formations proposées par Éditadapt dans son catalogue en vigueur, ainsi qu\u0026rsquo;à toutes les formations sur mesure définies pour un Client après validation conjointe sur le contenu, le format et la tarification proposée, par Éditadapt et le Client.\nArticle 4 : Commande de la formation # Pour être prise en compte par Éditadapt, toute formation doit faire l\u0026rsquo;objet d\u0026rsquo;un bon de commande écrit et signé par le Client. Dès réception du bon de commande, Éditadapt s\u0026rsquo;engage à traiter la commande dans les 5 jours. La proposition commerciale signée par le client fait office de bon de commande.\nArticle 5 : Modification de la commande \u0026ndash; Annulation ou report # Éditadapt se réserve le droit d\u0026rsquo;apporter à tout moment toute modification qu\u0026rsquo;elle juge utile à ses programmes et prestations de formation ainsi qu\u0026rsquo;au planning de ses formations. Elle se réserve le droit de modifier, sans avis préalable, les intervenants et de supprimer un ou plusieurs titres de sa gamme de formations.\nEn cas d\u0026rsquo;annulation pour quelque cause que ce soit (comme par exemple indisponibilité du formateur pour des raisons de maladie, panne d\u0026rsquo;électricité, indisponibilité du système informatique, nombre de participants insuffisant, conflits sociaux, conditions météorologiques) la (ou les) formation(s) commandée(s) sera(ont) reportée(s) à une date ultérieure sans dédommagement ni pénalité due au Client.\nEn cas de modification du programme ou du planning de la ou des formations, comme en cas d\u0026rsquo;annulation des formations, Éditadapt s\u0026rsquo;engage à prévenir les Clients ayant commandé ces formations, ou directement les participants à ces formations désignés par le Client préalablement inscrits 10 jours au moins avant le début de la ou des formations concernées. Une nouvelle date sera définie conjointement entre Éditadapt et le client.\nS\u0026rsquo;il souhaite annuler ou reporter sa participation à une ou plusieurs formations, le Client ne pourra le faire qu\u0026rsquo;en respectant scrupuleusement les conditions suivantes :\nToute annulation ou tout report d\u0026rsquo;inscription à une formation devra être signalée à Éditadapt par le Client lui-même, et non par les participants désignés par le Client pour la ou les formations commandées, par téléphone ou par courriel et doit être confirmée par courrier recommandé avec AR adressé à l\u0026rsquo;adresse du siège de Éditadapt.\nLes conséquences financières des annulations et reports sont les suivantes :\nTout report ou toute annulation intervenant plus de 5 jours ouvrés avant la date du début de la formation, la date prise en compte étant la réception du courrier recommandé avec AR dont il est fait état ci-dessus, ne donne lieu à aucun frais d\u0026rsquo;annulation ;\nTout report ou toute annulation intervenant entre 2 et 5 jours ouvrés avant la date du début de la formation, la date prise en compte étant la réception du courrier recommandé avec AR dont il est fait état ci-dessus, donne lieu à une facturation par Éditadapt égale à 50 % du prix convenu et définit par la proposition commerciale ou le bon de commande signé par le Client. Ce à titre d\u0026rsquo;indemnité forfaitaire à la charge du Client ;\nToute formation annulée ou reportée la veille ou le jour même où elle débute sera due intégralement par le Client à Éditadapt à titre d\u0026rsquo;Indemnité forfaitaire ;\nToute formation commencée sera due intégralement par le Client.\nArticle 6 : Prix # Les prestations de formation sont facturées au prix en vigueur au moment de la confirmation de la commande de formation.\nLe prix facturé par Éditadapt inclut la fourniture de la prestation de formation conforme aux exigences de qualité de Éditadapt.\nLes frais de repas, ainsi que les frais de déplacements et d\u0026rsquo;hébergement des participants à la formation ne sont pas inclus dans le prix de la prestation de formation.\nArticle 7 : Facturation # Une facture sera établie et remise au Client par Éditadapt de la façon suivante :\nà l\u0026rsquo;issue de la formation pour tout Client inscrit,\nLe prix de la prestation, non soumis à TVA, sera exprimé en Euro.\nArticle 8 : Paiement \u0026ndash; Modalités # Le prix des prestations de formation est payable comptant à l\u0026rsquo;issue de chaque séance de formation sauf accord préalable et écrit entre le Client et un responsable habilité de Éditadapt.\nÉditadapt étant un organisme de formation agréé, il est habilité à signer des conventions de formation. Les factures délivrées par Éditadapt tiennent lieu de convention simplifiée, mais le Client peut, sur simple demande, obtenir une convention détaillée et/ou une attestation de présence individuelle délivrée par Éditadapt.\nÉditadapt se réserve le droit d\u0026rsquo;exiger un prépaiement quinze jours avant le début de la formation. Dans ce cas le Client pourra se voir refuser l\u0026rsquo;accès à la formation si le paiement n\u0026rsquo;a pas été effectué dans les délais requis.\nDans le cas d\u0026rsquo;un financement par l\u0026rsquo;intermédiaire d\u0026rsquo;un OPCA, il appartient au Client d\u0026rsquo;obtenir la prise en charge des formations commandées auprès de cet organisme. Dans le cas où cette prise en charge n\u0026rsquo;est pas obtenue avant le début de la participation du Client à la formation considérée, le Client devra s\u0026rsquo;acquitter des sommes dues auprès de Éditadapt et fera son affaire du remboursement auprès de l\u0026rsquo;OPCA dont il dépend.\nArticle 9 : Paiement \u0026ndash; Retard ou défaut # Conformément aux dispositions de l\u0026rsquo;article L 441-6 du Code de commerce, le délai de paiement des sommes échues ne peut dépasser les trente jours fin de mois à compter de la date d\u0026rsquo;émission de la facture.\nToute somme non payée à l\u0026rsquo;échéance figurant sur la facture générera des pénalités de retard exigibles le jour suivant la date de règlement figurant sur la facture au taux d\u0026rsquo;intérêt légal appliqué par la Banque Centrale Européenne majoré de 10 points de pourcentage, qui ne peut toutefois être inférieur à trois fois le taux d\u0026rsquo;intérêt légal, ainsi qu\u0026rsquo;une indemnité forfaitaire de 40 € pour frais de recouvrement, conformément aux dispositions de l\u0026rsquo;article D 441-5 du Code du Commerce.\nLe montant de ces intérêts de retard sera imputé de plein droit sur toutes remises, ristournes ou rabais dus par Éditadapt.\nLe Client devra rembourser tous les frais occasionnés par le recouvrement contentieux des sommes dues, y compris et notamment les honoraires d\u0026rsquo;officiers ministériels (huissiers) ou d\u0026rsquo;auxiliaires de Justice.\nEn aucun cas, les paiements ne peuvent être suspendus ni faire l\u0026rsquo;objet d\u0026rsquo;une quelconque compensation sans l\u0026rsquo;accord écrit et préalable d\u0026rsquo;un responsable habilité par Éditadapt. Tout paiement partiel s\u0026rsquo;imputera d\u0026rsquo;abord sur la partie exigible de la créance, puis sur les sommes dont l\u0026rsquo;exigibilité est plus récente.\nArticle 10 : Propriété Intellectuelle \u0026ndash; Droits d\u0026rsquo;auteur # L\u0026rsquo;ensemble des documents remis au cours de la formation constitue des œuvres originales et à ce titre sont protégés par la législation sur la propriété intellectuelle et les droits d\u0026rsquo;auteur.\nEn conséquence, le Client s\u0026rsquo;interdit d\u0026rsquo;utiliser, copier, transmettre et généralement d\u0026rsquo;exploiter tout ou partie de ces documents, sans l\u0026rsquo;accord préalable et écrit d\u0026rsquo;un responsable habilité de Éditadapt.\nLe Client s\u0026rsquo;interdit d\u0026rsquo;effectuer toute copie de logiciels utilisés dans les stages de formation, à l\u0026rsquo;exception des exercices réalisés, à condition que les fichiers n\u0026rsquo;incluent en aucune façon des parties du programme protégé par un droit quelconque.\nLe Client se porte fort du respect de ces interdictions de la part des participants qu\u0026rsquo;il désignera pour assister aux séances de formation et déclare se porter, à cet effet, garant et responsable solidaire de ces participants.\nArticle 11 : Règlement intérieur pour le déroulement des formations # Lors de la participation aux séances de formation, le Client s\u0026rsquo;engage à respecter les dispositions du règlement intérieur de Éditadapt dont il déclare avoir pris connaissance et en accepter les termes.\nLe Client se porte fort du respect de ces dispositions de la part des participants qu\u0026rsquo;il désignera pour assister aux séances de formation et déclare se porter, à cet effet, garant et responsable solidaire de ces participants.\nArticle 12 : Notifications # Toutes notifications devant être effectuées dans le cadre de l\u0026rsquo;exécution des présentes Conditions Générales de Vente seront considérées comme réalisées si elles sont faites par lettre recommandée avec demande d\u0026rsquo;avis de réception aux adresses suivantes :\nÀ Gautier Chomel - Éditadapt : au 10 rue de la salle l\u0026rsquo;eveque, 34000 Montpellier.\nAu Client : à l\u0026rsquo;adresse indiquée par le Client lors de la commande.\nArticle 13 : Nullité d\u0026rsquo;une clause # Si l\u0026rsquo;une quelconque des dispositions des présentes Conditions Générales de Vente était annulée, cette nullité n\u0026rsquo;entraînerait pas la nullité des autres dispositions desdites Conditions Générales de Vente qui demeureront en vigueur entre Éditadapt et le Client.\nArticle 14 : Confidentialité des Données # Les informations demandées au Client sont nécessaires au traitement de sa commande.\nDans l\u0026rsquo;hypothèse où le Client consent à communiquer des données individuelles à caractère personnel, il dispose d\u0026rsquo;un droit individuel d\u0026rsquo;accès, de retrait et de rectification de ces données dans les conditions prévues par la loi n° 78-17 du 6 janvier 1978 relative à l\u0026rsquo;informatique, aux fichiers et aux libertés. Le Client doit adresser toute demande écrite à l\u0026rsquo;adresse du siège social de Éditadapt.\nArticle 15 : Compétence / contestation / loi applicable # En cas de difficulté d\u0026rsquo;interprétation ou d\u0026rsquo;exécution des présentes Conditions Générales de Vente, Éditadapt et le Client conviennent expressément que le Tribunal de Commerce de Nanterre sera le seul compétent.\nLes présentes Conditions Générales de Vente sont soumises pour leur interprétation et leur exécution à la loi française.\nFin du document\n"}).add({id:11,href:"/fr/docs/qualite/ea_ri/",title:"Règlement intérieur ",description:"Mis à jour le 28 avril 2022\nPRÉAMBULE # Règlement intérieur de l\u0026rsquo;organisme de formation Gautier Chomel - éditadapt, ci-après dénommé l\u0026rsquo;organisme de formation. Établi conformément aux articles L6352-3, L6352-4 et R6352-1 à R6352-15 du Code du travail.\nArticle 1er \u0026ndash; Champ d\u0026rsquo;application et objet # Le présent règlement s\u0026rsquo;applique à tous les stagiaires et ce pour la durée de la formation suivie. Il a pour objet de définir la règlementation liée à l\u0026rsquo;hygiène et à la sécurité ainsi que les règles relatives à la discipline, notamment les sanctions applicables et les droits des stagiaires dans le cadre de la procédure disciplinaire.",content:"Mis à jour le 28 avril 2022\nPRÉAMBULE # Règlement intérieur de l\u0026rsquo;organisme de formation Gautier Chomel - éditadapt, ci-après dénommé l\u0026rsquo;organisme de formation. Établi conformément aux articles L6352-3, L6352-4 et R6352-1 à R6352-15 du Code du travail.\nArticle 1er \u0026ndash; Champ d\u0026rsquo;application et objet # Le présent règlement s\u0026rsquo;applique à tous les stagiaires et ce pour la durée de la formation suivie. Il a pour objet de définir la règlementation liée à l\u0026rsquo;hygiène et à la sécurité ainsi que les règles relatives à la discipline, notamment les sanctions applicables et les droits des stagiaires dans le cadre de la procédure disciplinaire.\nArticle 2 - Hygiène et sécurité # La prévention des risques d\u0026rsquo;accidents et de maladies est impérative et exige de chacun le respect total de toutes les prescriptions applicables en matière d\u0026rsquo;hygiène et de sécurité.\nConformément à l\u0026rsquo;article R. 6352-1 du code du travail, lorsque la formation se déroule dans un établissement ou une entreprise doté d\u0026rsquo;un règlement intérieur, les mesures d\u0026rsquo;hygiène et de sécurité applicables aux stagiaires sont celles de ce dernier règlement. Les consignes générales et particulières de sécurité en vigueur lors de sessions de formation en présence doivent être strictement respectées sous peine de sanctions disciplinaires.\nArticle 3 : Comportement général # Chaque stagiaire s\u0026rsquo;engage à respecter les conditions générales de délivrance des formations, ainsi que l\u0026rsquo;ensemble des règles lié à l\u0026rsquo;utilisation des différents services de l\u0026rsquo;organisme de formation (forum, regroupement en présence, service pédagogique, tutorat, etc.) définies dans les conditions générales d\u0026rsquo;utilisation.\nTout comportement manifestement contraire aux bonnes mœurs (impolitesse, harcèlement, menace, injures, etc.) ou aux conditions générales précitées pourra faire l\u0026rsquo;objet d\u0026rsquo;une sanction.\nIl est notamment formellement interdit aux stagiaires :\n  de faire un usage commercial des informations, services et contenus\n fournis par l\u0026rsquo;organisme de formation,\n   de céder à titre gratuit ou payant ses identifiants d\u0026rsquo;accès à un\n tiers,\n   de diffuser au public les contenus pédagogiques ainsi que l\u0026rsquo;ensemble\n des activités liées,\n   d\u0026rsquo;avoir un comportement irrespectueux à l\u0026rsquo;égard de l\u0026rsquo;ensemble des\n personnels de l\u0026rsquo;organisme de formation ou les autres stagiaires, quel que soit le mode de communication utilisé,\n   de diffuser des coordonnées personnelles (adresses électroniques,\n adresses postales, numéros de téléphone\u0026hellip;).\n   Article 4 - Sanctions # Tout manquement au respect du présent règlement ainsi que tout agissement considéré comme fautif par l\u0026rsquo;organisme de formation pourra, en fonction de sa nature et de sa gravité, faire l\u0026rsquo;objet de l\u0026rsquo;une ou l\u0026rsquo;autre des sanctions énoncées ci-après par ordre croissant d\u0026rsquo;importance :\n  avertissement écrit par le directeur du site assurant la formation ;\n  blâme ;\n  suspension temporaire ou définitive d\u0026rsquo;accès à tout ou partie des\n services proposés par l\u0026rsquo;organisme de formation (forum, etc.) ;\n   exclusion temporaire de la formation ;\n  exclusion définitive de la formation.\n  Article 5 - Procédure disciplinaire # Aucune sanction ne peut être infligée au stagiaire sans que celui-ci ne soit informé dans le même temps et par écrit des griefs retenus contre lui.\nLorsque l\u0026rsquo;organisme de formation envisage une prise de sanction, il convoque le stagiaire par courriel ou par lettre recommandée avec accusé de réception ou remise à l\u0026rsquo;intéressé contre décharge en lui indiquant l\u0026rsquo;objet de la convocation, la date, l\u0026rsquo;heure et le lieu de l\u0026rsquo;entretien, sauf si la sanction envisagée n\u0026rsquo;a pas d\u0026rsquo;incidence sur la présence du stagiaire pour la suite de la formation. Le cas échéant, l\u0026rsquo;entretien pourra être effectué en présence ou par tout moyen de communication à distance.\nAu cours de l\u0026rsquo;entretien, le stagiaire a la possibilité de se faire assister par une personne de son choix, stagiaire ou salarié de l\u0026rsquo;organisme de formation. La convocation mentionnée à l\u0026rsquo;article précédent fait état de cette faculté. Lors de l\u0026rsquo;entretien, le motif de la sanction envisagée est indiqué au stagiaire : celui-ci a alors la possibilité de donner toute explication ou justification des faits qui lui sont reprochés.\nArticle 6 \u0026ndash; Mesure conservatoire # Lorsqu\u0026rsquo;une mesure conservatoire d\u0026rsquo;exclusion temporaire à effet immédiat est considérée comme indispensable par l\u0026rsquo;organisme de formation, aucune sanction définitive relative à l\u0026rsquo;agissement fautif à l\u0026rsquo;origine de cette exclusion ne peut être prise sans que le stagiaire n\u0026rsquo;ait été au préalable informé des griefs retenus contre lui et, éventuellement, qu\u0026rsquo;il ait été convoqué à un entretien et ait eu la possibilité de s\u0026rsquo;expliquer.\nArticle 7 - Prononcé et notification de la sanction # La sanction ne peut intervenir moins d\u0026rsquo;un jour franc ni plus de 15 jours après l\u0026rsquo;entretien.\nElle fait l\u0026rsquo;objet d\u0026rsquo;une notification écrite et motivée au stagiaire sous forme de lettre recommandée, ou d\u0026rsquo;une lettre remise contre décharge.\nLe cas échéant, l\u0026rsquo;organisme de formation informe concomitamment l\u0026rsquo;employeur, et éventuellement l\u0026rsquo;organisme paritaire prenant à sa charge les frais de formation, de la sanction prise.\n"}).add({id:12,href:"/fr/docs/",title:"Formations",description:"",content:""}).add({id:13,href:"/fr/docs/edada/ad_4_epub-scolaire/",title:"Adapter des manuels scolaires au format EPUB accessible",description:"Créer un livre numérique complexe nativement accessible et facile à transformer. Un programme de 3 jours.",content:"Mise à jour : novembre 2023\nDurée : 21 heures sur 3 jours\nObjectifs #  Savoir créer un fichier epub3 à partir d\u0026rsquo;un livre scolaire fourni en pdf. Savoir gérer les contenus complexes dans un fichier epub3. Savoir vérifier la conformité d\u0026rsquo;un fichier epub3. Savoir améliorer la qualité et l\u0026rsquo;accessibilité d\u0026rsquo;un fichier epub.  Programme #  Les bases HTML et CSS. Les balises spécifiques au format epub3. Les métadonnées. Insérer des schémas. Insérer des tableaux. Insérer des formules mathématiques. Automatisations. Modèles de fichiers. Bonnes pratiques.  Public # Transcripteur-Adaptateur, technicien supérieur, technicien spécialisé.\nPré requis #  Compréhension des handicaps liés à la lecture. Connaissance des supports de publication adaptés aux handicaps.  Moyens pédagogiques #  Méthode active alternant apports théoriques, démonstrations et ateliers pratiques. Études de cas concrets à partir de situations des participants. Échanges personnalisés. Guide de référence, ressources et exercices.  Évaluation #  QCM. Évaluation orale à chaud. Questionnaire à froid.  Formateur # 25 ans d\u0026rsquo;expérience dans la production éditoriale dont 12 ans de pratique de publication adaptées à des besoins spécifiques. Formateur confirmé.\ntarif # Tous nos tarifs sont hors taxe et exonérés de TVA (article 261.4.4 a du CGI)\n Inter entreprises : 500 euros par personne. Inter entreprise à distance : 300 euros par personne. Intra entreprise : 1500 euros (jusqu\u0026rsquo;à 8 personnes).  dates et modalités #  Formation accessible aux personnes en situation de handicap. Inscription 3 semaines avant le début de la formation. Les sessions inter entreprises sont ouvertes à partir de 3 inscrits. Les sessions à distance se tiennent via l\u0026rsquo;application Zoom sur deux demi journées. Sessions à distance (pas de session programmée) Sessions inter en entreprise à Montpellier (pas de session programmée) Contact: formations @ editadapt.net (supprimer les espaces)  "}).add({id:14,href:"/fr/docs/ednac/nac_5_graphiques/",title:"Décrire les images et les ressources visuelles",description:"Mise à jour : avril 2022 Durée : 7 heures sur 1 journée\nobjectifs #  Comprendre les besoins de description en fonction du type d\u0026rsquo;image Savoir quelles ressources graphiques sont à décrire Savoir décrire une image dans son contexte  programme #  Utilité de la description des ressources graphiques  Sens Fonction Contexte Types de ressources graphiques   Solutions techniques  Texte court Texte long Liens Présnetation visuelle des descriptions   Décisions et choix éditoriaux  Decrire où ne pas décrire Dessins, Tableaux, Photographies, Bandes dessinées et romans graphiques Textes en graphiques Les représentations de données    publics # Responsables de contenus éditoriaux, auteurs, producteurs de contenus graphiques.",content:"Mise à jour : avril 2022 Durée : 7 heures sur 1 journée\nobjectifs #  Comprendre les besoins de description en fonction du type d\u0026rsquo;image Savoir quelles ressources graphiques sont à décrire Savoir décrire une image dans son contexte  programme #  Utilité de la description des ressources graphiques  Sens Fonction Contexte Types de ressources graphiques   Solutions techniques  Texte court Texte long Liens Présnetation visuelle des descriptions   Décisions et choix éditoriaux  Decrire où ne pas décrire Dessins, Tableaux, Photographies, Bandes dessinées et romans graphiques Textes en graphiques Les représentations de données    publics # Responsables de contenus éditoriaux, auteurs, producteurs de contenus graphiques.\nPré requis # Manipuler des images ou des ressources graphiques dans un contexte éditorial.\nMoyens pédagogiques #  Méthode active alternant apports théoriques, démonstrations et ateliers pratiques. Études de cas concrets à partir de situations des participants. Échanges personnalisés. Guide de référence, ressources et exercices.  Évaluation #  QCM. Évaluation orale à chaud. Questionnaire à froid.  Formateur # 25 ans d\u0026rsquo;expérience dans la production éditoriale dont 12 ans de pratique de publication adaptées à des besoins spécifiques. Formateur confirmé.\ntarif # Tous nos tarifs sont hors taxe et exonérés de TVA (article 261.4.4 a du CGI)\n Inter entreprises : 500 euros par personne. Inter entreprise à distance : 300 euros par personne. Intra entreprise : 1500 euros (jusqu\u0026rsquo;à 8 personnes).  dates et modalités #  Formation accessible aux personnes en situation de handicap. Inscription 3 semaines avant le début de la formation. Les sessions inter entreprises sont ouvertes à partir de 3 inscrits. Les sessions à distance se tiennent via l\u0026rsquo;application Zoom sur deux demi journées. Sessions à distance (pas de session programmée) Sessions inter en entreprise à Montpellier (pas de session programmée) Contact: formations @ editadapt.net (supprimer les espaces)  "}).add({id:15,href:"/fr/docs/edada/ad_2_adobe/",title:"InDesign, Acrobat et Photoshop pour le travail d'adaptation",description:"Objectifs #  Utiliser les outils Adobe Creative Suite pour l\u0026rsquo;édition de textes et d\u0026rsquo;images. Savoir modifier un fichier source éditeur pour une adaptation en gros caractères. Savoir créer un fichier indesign et réaliser une mise en page. Savoir exporter un fichier indesign aux formats epub et pdf accessibles. Connaître les spécificités de fichier permettant une exportation structurée et réutilisable liée à l'accessibilité pour les personnes empêchées de lire.  Programme #  Interface \u0026amp; fonctionnement général des logiciels.",content:"Objectifs #  Utiliser les outils Adobe Creative Suite pour l\u0026rsquo;édition de textes et d\u0026rsquo;images. Savoir modifier un fichier source éditeur pour une adaptation en gros caractères. Savoir créer un fichier indesign et réaliser une mise en page. Savoir exporter un fichier indesign aux formats epub et pdf accessibles. Connaître les spécificités de fichier permettant une exportation structurée et réutilisable liée à l'accessibilité pour les personnes empêchées de lire.  Programme #  Interface \u0026amp; fonctionnement général des logiciels. Gestion et compréhension des fichiers indd, ai, psd et pdf. Création d\u0026rsquo;un fichier pour une impression papier. Création d\u0026rsquo;un fichier pour une impression en relief. Création d\u0026rsquo;un fichier pour la production de documents et ouvrages numériques accessibles. Modification d\u0026rsquo;un fichier éditeur au format indd, ai, psd et pdf. Importations, exportations et interopérabilité. Formats structurés et automatisations (XML, GREP, expressions régulières). Modèles de fichiers. Bonnes pratiques.  Public # Transcripteur-Adaptateur, technicien supérieur, technicien spécialisé.\nPré requis #  Compréhension des handicaps liés à la lecture. Connaissance des supports de publication adaptés aux handicaps. Licence d\u0026rsquo;utilisation Adobe InDesign.  Moyens pédagogiques #  Méthode active alternant apports théoriques, démonstrations et ateliers pratiques. Études de cas concrets à partir de situations des participants. Échanges personnalisés. Guide de référence, ressources et exercices.  Évaluation #  QCM. Évaluation orale à chaud. Questionnaire à froid.  Formateur # 25 ans d\u0026rsquo;expérience dans la production éditoriale dont 12 ans de pratique de publication adaptées à des besoins spécifiques. Formateur confirmé.\nDurée # 35 heures sur 5 journées.\ntarif # Tous nos tarifs sont hors taxe et exonérés de TVA (article 261.4.4 a du CGI)\n Inter entreprises : 500 euros par personne et par jour. Inter entreprise à distance : 300 euros par personne et par jour. Intra entreprise : 1500 euros (jusqu\u0026rsquo;à 8 personnes) par jour.  dates et modalités #  Formation accessible aux personnes en situation de handicap. Inscription 3 semaines avant le début de la formation. Les sessions inter entreprises sont ouvertes à partir de 3 inscrits. Les sessions à distance se tiennent via l\u0026rsquo;application Zoom sur deux demi journées. Sessions à distance (pas de session programmée) Sessions inter en entreprise à Montpellier (pas de session programmée) Contact: formations @ editadapt.net (supprimer les espaces)  "}).add({id:16,href:"/fr/docs/qualite/qualiopi/",title:"Certification Qualiopi",description:"Certifié Qualiopi de avril 2023 à avril 2025, éditadapt n\u0026rsquo;a pas renouvelé sa certification Qualiopi pour cause de coût trop élevé en regard des avantages.\nQualiopi Délivrée par Certifopac. La certification qualité a été délivrée au titre de la catégorie d’action suivante : L.6313-1 - 1° Actions de formation\n[Certification Qualiopi n°50341149-1](https://certifopac.fr/qualiopi/verification-certificat/?siren=483764585) -- ",content:"Certifié Qualiopi de avril 2023 à avril 2025, éditadapt n\u0026rsquo;a pas renouvelé sa certification Qualiopi pour cause de coût trop élevé en regard des avantages.\nQualiopi Délivrée par Certifopac. La certification qualité a été délivrée au titre de la catégorie d’action suivante : L.6313-1 - 1° Actions de formation\n[Certification Qualiopi n°50341149-1](https://certifopac.fr/qualiopi/verification-certificat/?siren=483764585) -- "}).add({id:17,href:"/fr/docs/partenaires/crfcb/",title:"CFCB Bretagne, Pays de la Loire",description:"Depuis 2020, nous dispensons des formations de 6 heures à distance :\n Sensibilisation à l’accessibilité des ressources numériques en bibliothèque État des lieux de l’édition adaptée en France et dans le monde  Le Centre de Formation aux Carrières des Bibliothèques Bretagne Pays de la Loire fait partie d\u0026rsquo;un réseau national de 12 CRFCB (Centres Régionaux de Formation aux Carrières des Bibliothèques) qui propose, à toutes les catégories de personnels des bibliothèques ou futurs professionnels, des stages de formation continue, des journées et voyages d’étude, des préparations aux concours des bibliothèques d\u0026rsquo;Etat et territoriales, des formations longues (formation professionnelle de base ou de spécialisation, parfois sous forme de DU).",content:"Depuis 2020, nous dispensons des formations de 6 heures à distance :\n Sensibilisation à l’accessibilité des ressources numériques en bibliothèque État des lieux de l’édition adaptée en France et dans le monde  Le Centre de Formation aux Carrières des Bibliothèques Bretagne Pays de la Loire fait partie d\u0026rsquo;un réseau national de 12 CRFCB (Centres Régionaux de Formation aux Carrières des Bibliothèques) qui propose, à toutes les catégories de personnels des bibliothèques ou futurs professionnels, des stages de formation continue, des journées et voyages d’étude, des préparations aux concours des bibliothèques d\u0026rsquo;Etat et territoriales, des formations longues (formation professionnelle de base ou de spécialisation, parfois sous forme de DU). Le réseau s\u0026rsquo;est doté depuis 2017 d\u0026rsquo;une plateforme sur laquelle on retrouve toute l\u0026rsquo;offre de formation du réseau.\nCFCB Bretagne Pays de la Loire\nRéseau des CRFCB\n"}).add({id:18,href:"/fr/docs/partenaires/edinovo/",title:"Edinovo / Asfored",description:"Interventions sur deux formations.\nL’accessibilité numérique pour tous Intégrer l’accessibilité à son projet éditorial\nEdinovo Formation est une filiale de l\u0026rsquo;Asfored, organisme de formation spécialisé dans le secteur de l\u0026rsquo;édition, la communication et la culture. Edinovo et le pôle dédié aux activités de formation professionnelle continue.",content:"Interventions sur deux formations.\nL’accessibilité numérique pour tous Intégrer l’accessibilité à son projet éditorial\nEdinovo Formation est une filiale de l\u0026rsquo;Asfored, organisme de formation spécialisé dans le secteur de l\u0026rsquo;édition, la communication et la culture. Edinovo et le pôle dédié aux activités de formation professionnelle continue.\n"}).add({id:19,href:"/fr/docs/qualite/stagiaires/",title:"Engagement des participants",description:"Éditadapt met en œuvre tous les moyens pédagogiques pour favoriser l’engagement des\nbénéficiaires :\n questionnaire en amont pour le recueil des besoins, méthodes participatives tout au long de la formation, suivi personnalisé.  Procédure de gestion des abandons # Si un abandon était constaté, la procédure ci-dessous serait mise en œuvre. La procédure sera suivie grace à l\u0026rsquo;inscription au registre des abandons.\n Après un délai raisonnable et sans information de la part du stagiaire, nous informons le prescripteur de l’absence du stagiaire par email.",content:"Éditadapt met en œuvre tous les moyens pédagogiques pour favoriser l’engagement des\nbénéficiaires :\n questionnaire en amont pour le recueil des besoins, méthodes participatives tout au long de la formation, suivi personnalisé.  Procédure de gestion des abandons # Si un abandon était constaté, la procédure ci-dessous serait mise en œuvre. La procédure sera suivie grace à l\u0026rsquo;inscription au registre des abandons.\n Après un délai raisonnable et sans information de la part du stagiaire, nous informons le prescripteur de l’absence du stagiaire par email. Dans l’hypothèse d’un abandon avéré, nous adressons un email au stagiaire dans lequel une analyse des raisons sera demandée.\n« Madame, Monsieur,\nVous nous avez fait par de votre souhait d’abandonner la formation intitulée xxx.\nNous en sommes désolés. Dans le cadre de notre gestion des ruptures de convention, pouvez-vous nous indiquer les raisons de votre décision ?\nManque de temps\nManque de motivation pour la thématique\nCaractère obligatoire de la formation\nAutres (merci de préciser) :\nNous reviendrons vers vous très prochainement après analyse de vos raisons pour vous proposer une alternative pouvant répondre à vos attentes ou contraintes.\nNous restons disponibles pour toute question.\nDans l’attente de vous lire, je vous prie d’agréer nos meilleures salutations. » Analyse et détermination des causes Traitement des causes : proposition de solution en adéquation avec les causes invoquées, Échange avec le bénéficiaire et le prescripteur sur les alternatives proposées. Relance systématique effectuée avec une proposition d’alternative adressée par email aux parties prenantes Validation ou invalidation de l’abandon Envoi d’un formulaire à compléter et à signer (Attestation d’abandon de formation) :\n« Je soussigné.e Madame, Monsieur XXX, certifie vouloir abandonner définitivement la formation\n(Intitulé) du (dates xxx au xxx).\nPour valoir ce que de droit.\nDate et signature du stagiaire »  "}),search.addEventListener('input',b,!0);function b(){var b,e;const d=5;b=this.value,e=a.search(b,{limit:d,enrich:!0});const c=new Map;for(const a of e.flatMap(a=>a.result)){if(c.has(a.doc.href))continue;c.set(a.doc.href,a.doc)}if(suggestions.innerHTML="",suggestions.classList.remove('d-none'),c.size===0&&b){const a=document.createElement('div');a.innerHTML=`No results for "<strong>${b}</strong>"`,a.classList.add("suggestion__no-results"),suggestions.appendChild(a);return}for(const[h,g]of c){const b=document.createElement('div');suggestions.appendChild(b);const a=document.createElement('a');a.href=h,b.appendChild(a);const e=document.createElement('span');e.textContent=g.title,e.classList.add("suggestion__title"),a.appendChild(e);const f=document.createElement('span');if(f.textContent=g.description,f.classList.add("suggestion__description"),a.appendChild(f),suggestions.appendChild(b),suggestions.childElementCount==d)break}}})()